contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(this).balance;
        uint contractEtherBefore = address(c).balance;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        assert(
            c.balances(address(this)) == balBefore - amount &&
            address(this).balance == etherBefore + amount &&
            address(c).balance == contractEtherBefore - amount &&
            c.MinSum() == 0
        );
    }
    receive() external payable {}
    fallback() external payable {}
}

